+    let latest: IngestionKey = "00000000-0000-4000-8000-000000000001".parse()?;
+    create_run(&data, &older, 10)?;
+    create_run(&data, &latest, 20)?;
+    fs::create_dir(data.join("not-an-ingestion-key"))?;
